import{_ as n,o,c as d,a5 as l}from"./chunks/framework.CslsFoWx.js";const a="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/01-accueil-en.png",t="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/02-accueil-ar.png",r="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/03-tuto-en.png",s="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/04-tuto-ar.png",i="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/05-messages-ar.png",_=JSON.parse(`{"title":"Centre d'aide en anglais et en arabe (carte Trello P2, 08/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-aide-en-ar.md","filePath":"generated/preuves/2026-11-08-aide-en-ar.md","lastUpdated":null}`),c={name:"preuves/2026-11-08-aide-en-ar.md"};function u(g,e,p,m,h,f){return o(),d("div",null,[...e[0]||(e[0]=[l('<h1 id="centre-d-aide-en-anglais-et-en-arabe-carte-trello-p2-08-11-2026" tabindex="-1">Centre d&#39;aide en anglais et en arabe (carte Trello P2, 08/11/2026) <a class="header-anchor" href="#centre-d-aide-en-anglais-et-en-arabe-carte-trello-p2-08-11-2026" aria-label="Permalink to &quot;Centre d&#39;aide en anglais et en arabe (carte Trello P2, 08/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-aide-en-ar</code> · 5 image(s) · 0 trace(s)</p><div><p>Le centre d&#39;aide <code>help/</code> existe maintenant en trois langues, avec les mêmes chemins de page :</p><ul><li>le français à la racine <code>/</code>, inchangé ;</li><li>l&#39;anglais sous <code>/en/</code> ;</li><li>l&#39;arabe sous <code>/ar/</code>, affiché de droite à gauche (<code>dir=&quot;rtl&quot;</code>).</li></ul><p>Les 153 pages sont traduites dans chaque langue : l&#39;accueil, les 13 rubriques, les tutoriels, le dépannage et l&#39;index des messages d&#39;erreur.</p><p>Captures prises après <code>npm run build</code>, sur <code>vitepress preview</code> avec Chrome headless. Elles sont en thème sombre parce que la machine l&#39;est.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+a+'" alt=""></td><td><strong>01 — Accueil en anglais.</strong> La barre du haut est traduite (Getting started, Back office, Devices, Troubleshooting), avec le sélecteur de langue et la recherche « Search the help ». Les cartes de rubrique et le nombre de tutoriels sont comptés dans la langue de la page.</td></tr><tr><td><img src="'+t+'" alt=""></td><td><strong>02 — Accueil en arabe.</strong> Toute la mise en page passe de droite à gauche : barre, héros, recherche, cartes. Les termes sont ceux du produit (الكتالوج, الحرفاء, المتابعة…). Les cartes ne sont plus soulignées, un défaut qui existait aussi en français.</td></tr><tr><td><img src="'+r+'" alt=""></td><td><strong>03 — Tutoriel en anglais</strong> (Catalog › VAT rates). Fiche du tutoriel traduite (Goal, Required role, Where, Time) avec l&#39;encadré « screenshots in French ». Étapes numérotées, captures françaises réutilisées, légendes traduites.</td></tr><tr><td><img src="'+s+'" alt=""></td><td><strong>04 — Le même tutoriel en arabe.</strong> La pastille de numéro et le trait des étapes passent à droite. La barre latérale et la table « في هذه الصفحة » sont de droite à gauche. L&#39;encadré « لقطات الشاشة… بالفرنسية » est présent, et les chiffres restent en 0-9.</td></tr><tr><td><img src="'+i+'" alt=""></td><td><strong>05 — Index des messages d&#39;erreur en arabe.</strong> Chaque message est affiché tel que l&#39;écran arabe le montre, suivi de l&#39;original français entre parenthèses. Les ancres <code>#lettre-…</code> sont conservées. Le tableau se lit de droite à gauche.</td></tr></tbody></table><p>Vérification au téléphone, dans le volet navigateur à 375 px, sur <code>/ar/guide/appareil-caisse/encaisser</code> : <code>scrollWidth</code> vaut 375, donc aucun défilement horizontal, avec <code>dir=&quot;rtl&quot;</code> et <code>lang=&quot;ar&quot;</code>. Le sélecteur de langue ouvre la même page dans l&#39;autre langue (<code>/guide/…</code> et <code>/en/guide/…</code> depuis <code>/ar/guide/…</code>). Il n&#39;y a pas de capture à 375 px : Chrome headless impose une fenêtre plus large et rogne l&#39;image.</p><h2 id="aide-contextuelle-dans-la-langue-de-l-utilisateur" tabindex="-1">Aide contextuelle dans la langue de l&#39;utilisateur <a class="header-anchor" href="#aide-contextuelle-dans-la-langue-de-l-utilisateur" aria-label="Permalink to &quot;Aide contextuelle dans la langue de l&#39;utilisateur&quot;">​</a></h2><p>Le lien d&#39;aide ajoute le préfixe de la langue (<code>/en/</code> ou <code>/ar/</code>) devant la page :</p><ul><li><strong>Back-office :</strong> le bouton « ? », le lien « En savoir plus », « Centre d&#39;aide » et la liste « Bien démarrer » suivent la langue du back-office (<code>HelpLinkService</code> et <code>I18nService.lang</code>). Couvert par des tests web.</li><li><strong>Apps :</strong> « Aide en ligne » (caisse, salle, cuisine, borne, diagnostic) suit <code>caisse.locale</code>, via <code>CentreAide.url(role, langue)</code> dans <code>:shared</code>. Couvert par des tests shared, Android (<code>WaiterMenuLinesTest</code>) et iOS (<code>MenuSalleTests</code>).</li></ul><h2 id="hors-de-ce-lot" tabindex="-1">Hors de ce lot <a class="header-anchor" href="#hors-de-ce-lot" aria-label="Permalink to &quot;Hors de ce lot&quot;">​</a></h2><ul><li><strong>Captures par langue.</strong> Elles restent en français (encadré automatique sur chaque tutoriel EN / AR). Une carte séparée pourra les refaire par langue.</li><li><strong>Messages du produit sans traduction.</strong> Certains messages du serveur ou textes écrits en dur s&#39;affichent en français dans l&#39;app en anglais ou en arabe. L&#39;aide les cite donc en français, avec leur traduction. Exemples : <ul><li>bandeaux d&#39;abonnement ;</li><li>erreurs d&#39;import CSV ;</li><li>refus de publication ;</li><li><code>Politique de vente publiée…</code> (<code>checkout-policy.ts</code>) ;</li><li><code>Import appliqué…</code> (<code>catalog-import.ts</code>) ;</li><li><code>Thème publié…</code> (<code>appearance.ts</code>) ;</li><li>boutons d&#39;envoi du reçu (<code>Receipts.kt</code>) ;</li><li><code>Part 1/2</code> (<code>OrderCheckout.kt</code>).</li></ul></li></ul></div><h2 id="galerie" tabindex="-1">Galerie <a class="header-anchor" href="#galerie" aria-label="Permalink to &quot;Galerie&quot;">​</a></h2><div class="proof-grid"><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/01-accueil-en.png" target="_blank"><img src="'+a+'" alt="01-accueil-en.png" loading="lazy"></a><figcaption>01-accueil-en.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/02-accueil-ar.png" target="_blank"><img src="'+t+'" alt="02-accueil-ar.png" loading="lazy"></a><figcaption>02-accueil-ar.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/03-tuto-en.png" target="_blank"><img src="'+r+'" alt="03-tuto-en.png" loading="lazy"></a><figcaption>03-tuto-en.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/04-tuto-ar.png" target="_blank"><img src="'+s+'" alt="04-tuto-ar.png" loading="lazy"></a><figcaption>04-tuto-ar.png</figcaption></figure><figure class="proof"><a href="/VendoraSystem-docs/captures/2026-11-08-aide-en-ar/05-messages-ar.png" target="_blank"><img src="'+i+'" alt="05-messages-ar.png" loading="lazy"></a><figcaption>05-messages-ar.png</figcaption></figure></div>',5)])])}const v=n(c,[["render",u]]);export{_ as __pageData,v as default};
